  ('a1000000-0000-0000-0000-000000000003', '4bc6aadc-1067-4c95-9a45-ee784ff7373b', 'Йога — это не просто спорт, это медитация в движении.', NOW(), NOW()),
  ('a1000000-0000-0000-0000-000000000004', 'bdd1aa18-d820-48a2-9ca3-e32433ab5bc7', 'Бегаю уже неделю, чувствую прилив энергии!', NOW(), NOW()),
